"""Write the bilingual publication narrative from the verified display projection."""
import argparse
import json
import pathlib


def table(head, rows):
    return '| ' + ' | '.join(head) + ' |\n|' + '|'.join('---' for _ in head) + '|\n' + ''.join('| ' + ' | '.join(map(str, row)) + ' |\n' for row in rows)


def documents(case):
    data = json.loads((case / 'publication/summary/project.json').read_text())
    assert all(data['status'].values()), 'Do not generate verification-success narrative for blocked gates'
    def f(value, d=3):
        return 'NOT_RECORDED' if value is None else f'{value:.{d}f}'
    tech = 'followups/nvfp4-technical-r1'
    cap = table(['KV', 'bytes/token', 'actual pool bytes', 'blocks ×16', 'token slots'], [[r['kv'], r['bytes_per_token'], r['actual_pool_bytes'], r['blocks'], r['token_slots']] for r in data['capacity']])
    perf = table(['Input', 'C', 'B16 req/s', 'F4 req/s', 'F4/B16 median [3-round range]', 'success B16 / F4'], [[str(r['length'] // 1024) + 'K', r['concurrency'], f(r['B16_requests_per_second']['median']), f(r['F4_requests_per_second']['median']), f(r['ratio_median']) + ' [' + f(r['ratio_min']) + ', ' + f(r['ratio_max']) + ']', str(r['B16_success']) + '/24 / ' + str(r['F4_success']) + '/24'] for r in data['summary']])
    resources = table(['Input','C','B16/F4 median TTFT s','B16/F4 decode ms/token','B16/F4 queue s','B16/F4 preemptions','B16/F4 device peak MiB'], [[str(r['length']//1024)+'K',r['concurrency'], '/'.join(f(r[k+'_median_client_ttft_seconds']['median']) for k in ('B16','F4')), '/'.join(f(r[k+'_median_client_decode_ms_per_token']['median']) for k in ('B16','F4')), '/'.join(f(r[k+'_request_queue_time_seconds_mean']['median']) for k in ('B16','F4')), str(r['B16_preemptions'])+' / '+str(r['F4_preemptions']), '/'.join(f(r[k+'_sampled_device_peak_MiB']['max'],0) for k in ('B16','F4'))] for r in data['summary']])
    startups = table(['Owned server','Mode','Load/compile/warmup ready seconds','Total attempt wall seconds'], [[r['name'],r['mode'],f(r['ready_seconds']),f(r['wall_seconds'])] for r in data['worker']['attempts']])
    costs = table(['Phase', 'model request attempts', 'responses received', 'observed output tokens'], [[k, v['model_request_attempts'], v['responses_received'], v['output_tokens']] for k, v in data['counts'].items()])
    sanity = table(['Input', 'B16 copy exact /4', 'F4 copy exact /4', 'equal token sequences /8'], [[str(length // 1024) + 'K', sum(r['B16_exact_answer'] is True for r in data['fidelity'] if r['length'] == length), sum(r['F4_exact_answer'] is True for r in data['fidelity'] if r['length'] == length), sum(r['token_sequences_equal'] for r in data['fidelity'] if r['length'] == length)] for length in (8192, 16384)])
    primary = [r for r in data['summary'] if r['length'] == 16384 and r['concurrency'] in (2, 4)]
    ratios = ' · '.join('16K/C' + str(r['concurrency']) + ': ' + f(r['ratio_median'], 2) + '× [' + f(r['ratio_min'], 2) + ', ' + f(r['ratio_max'], 2) + ']' for r in primary)
    all_primary_positive = all(r['ratio_min'] > 1 for r in primary)
    conclusion_ko = '등록한16K/C2·C4 workload의 세 라운드 모두에서 serving gain을 관측했습니다.' if all_primary_positive else 'NVFP4 KV storage/capacity를 검증했고, serving 결과는 조건·라운드별 표로 제시합니다. 주 비교 전반의 일관된 gain은 확인하지 못했습니다.'
    conclusion_en = 'Serving gains were observed in every registered16K/C2 and C4 paired round.' if all_primary_positive else 'NVFP4 KV storage/capacity is verified; serving trade-offs are reported by condition and round. A consistent gain across all primary comparisons was not established.'
    for lang in ('ko', 'en'):
        ko = lang == 'ko'
        suffix = '.ko.md' if ko else '.md'
        txt = lambda k, e: k if ko else e
        title = txt('Case016 — RTX 5080에서 NVFP4 KV 캐시 검증: 같은 메모리로 더 긴 문맥을 수용할 수 있을까?', 'Case016 — NVFP4 KV Cache on RTX5080: Storage, Correctness, and Serving Performance')
        intro = txt('vLLM0.32.0과 FlashInfer의 실제 압축 KV 경로를 연결하고, 저장·읽기·고정 메모리 용량·동시 요청 비용을 검증하는 도구를 구현했습니다. Qwen3-4B의 가중치는 BF16으로 유지했습니다.', 'Built tools integrating vLLM0.32.0 and FlashInfer native compressed KV to verify storage/read correctness, fixed-pool capacity and concurrent-request costs. Qwen3-4B weights remain BF16.')
        headline = txt('같은 약4GiB pool에서 B16의29,120슬롯을 NVFP4의103,552슬롯으로 늘려 token 수용량 ', 'At the same approximately4GiB pool, B16 has29,120 slots and NVFP4 has103,552, a token-capacity ratio of ') + f(data['capacity_ratio'], 4) + '×. ' + (conclusion_ko if ko else conclusion_en)
        links = '[Report](REPORT' + suffix + ') · [CPU / GPU reproduction](REPRODUCE' + suffix + ') · [Runner](' + tech + '/src/nvfp4_technical/runner.py) · [Raw / CSV](' + tech + '/results/) · [Stage map](STAGE_MAP.md)'
        readme = '# ' + title + '\n\n' + intro + '\n\n' + headline + '\n\n' + '**' + ratios + '**\n\n' + txt('위 비율은 성공 HTTP 요청/s의 F4/B16 비율이며3라운드 중앙값과 범위입니다. 전체 VRAM 감소율·agent 성공률·100K 단일 문맥 지원을 뜻하지 않습니다.', 'Ratios are successful HTTP requests/s for F4/B16, with three-round median and range. They are not total VRAM reductions, agent-success gains or100K single-context support.') + '\n\n' + links + '\n\n' + cap + '\n' + perf
        readme += '\n' + txt('처음 보는 용어: KV 캐시는 모델이 읽은 내용의 중간 계산값을 저장하는 공간입니다. BF16은16비트 기준선, NVFP4는4비트 값과 block scale을 함께 저장하는 형식입니다. C는 동시에 보내는 client 요청 수, token은 모델이 읽는 글 조각입니다. req/s는 초당 성공 요청 수로 높을수록 좋습니다.', 'Terms: a KV cache stores intermediate values for text already read by the model. BF16 is the16-bit baseline; NVFP4 stores four-bit values with block scales. C is concurrent client requests; a token is a text unit read by the model. Higher req/s means more successful requests per second.')
        readme += '\n\n' + txt('이전 agent DEV는 B16 0/48·F4 6/48, 같은12개 과제의 반복입니다. 기준선 gate NOT_MET과96개 원 판정·CPU 감사는 [원형 안내](STAGE_MAP.md)에 보존했습니다. Agent P2/P3는 실행하지 않았습니다. 한영 Pages builder에는 연결했으며 수동 배포는 이번 범위에서 실행하지 않습니다.', 'The earlier agent DEV retains B16 0/48 and F4 6/48, repeating12 tasks. The NOT_MET baseline gate,96 original verdicts and CPU audit are preserved in the [stage map](STAGE_MAP.md). Agent P2/P3 were not run. Bilingual Pages build integration is prepared; manual deployment is outside this execution.') + '\n'
        (case / ('README' + suffix)).write_text(readme)
        headings = txt(['배경', '질문', '기술 원리', '방법', '실험', '결과', '분석', '결론', '재현·출처'], ['Background', 'Questions', 'Technical principles', 'Method', 'Experiment', 'Results', 'Analysis', 'Conclusion', 'Reproduction and sources'])
        anchors = ['background', 'questions', 'principles', 'method', 'experiment', 'results', 'analysis', 'conclusion', 'sources']
        report = '# ' + title + '\n\n' + intro + '\n\n' + headline + '\n\n' + '\n'.join(str(i + 1) + '. [' + h + '](#' + a + ')' for i, (h, a) in enumerate(zip(headings, anchors))) + '\n'
        bodies = []
        bodies.append(txt('원래 장문 agent 탐색에서는 기준선 완주율이 낮았습니다. 원 실패를 보존하고, 이번 후속은 실제 압축 KV의 저장·읽기와 수용량·서빙 비용이라는 기술 질문으로 한정했습니다. 새 agent 과제·학습·가중치 양자화를 추가하지 않았습니다.', 'The original long-context agent exploration had a weak baseline. Preserving those failures, this follow-up focuses on native compressed-KV storage/read, capacity and serving costs. It adds no agent task, training or weight quantization.'))
        bodies.append(txt('TECH_PATH_VALID: 실제 SM120/36층에서 packed KV를 저장·읽는가? TECH_NUMERIC_VALID: 같은 압축 캐시의 두 dequant 해석과 실제 attention 유한성이 확인되는가? CAPACITY_VALID: 같은 pool의 실제 bytes와 슬롯이 일치하는가? SERVING_MEASURED: 고정 요청 집합을 전 조건에서 관측했는가? 속도 향상을 완료 조건으로 삼지 않았습니다.', 'TECH_PATH_VALID checks native packed reads/writes on SM120 across36 layers. TECH_NUMERIC_VALID checks two dequant interpretations and finite actual attention outputs. CAPACITY_VALID checks actual bytes and slots at the same pool. SERVING_MEASURED requires the fixed request set across all conditions. Faster performance is not required for completion.'))
        bodies.append(txt('B16: 2×36×8×128×2=147456B/token. F4: packed data36864 + FP8 block scales4608 =41472B/token. 비율147456/41472=3.5556이며 실제 page 정렬 뒤 슬롯 비율과 조금 다릅니다. 공유 storage의 view는 중복 계수하지 않았습니다. F4는 uint8 packed values와 FP8 E4M3 block scale, 고정 global scale1을 사용했습니다. 짧은 profile은 NVFP4 writer와 압축 데이터를 읽는 FlashInfer FA2 경로를 보여줍니다. BF16 fallback과 FA2 read를 구분합니다.', 'B16 uses2×36×8×128×2=147456B/token. F4 uses36864 packed-data bytes plus4608 FP8 block-scale bytes, totaling41472B/token. The arithmetic ratio3.5556 differs slightly from page-aligned slot capacity. Shared-storage views are counted once. F4 uses packed uint8 values, FP8 E4M3 block scales and fixed global scale1. Short profiles show the NVFP4 writer and FlashInfer FA2 reading compressed data, rather than BF16 storage fallback.'))
        bodies.append(txt('모델 revision은 `cdbee75f17c01a7cc42f958dc650907174af0554`,36층·Q32/KV8·head_dim128입니다. 두 조건에4GiB 목표 pool·context28672·max_num_seqs4·chunked prefill2048·prefix caching OFF·async scheduling OFF·BF16 weights를 공통 적용했습니다. 두 CUDA graph gate가 통과해 실제 compilation mode FULL_AND_PIECEWISE를 공통 사용했습니다. B16/F4 모두 decode는 XQA를 사용했고 F4 prefill은 NVFP4 FA2였습니다. XQA 호출은 packed NVFP4 data와 block scale을 받습니다. `nvfp4_fa2=True`와 `impl.use_xqa=None`은 decode 미사용의 근거가 아닙니다.', 'Model revision is`cdbee75f17c01a7cc42f958dc650907174af0554`, with36 layers,Q32/KV8 and head_dim128. Both use a4GiB target pool, context28672,max_num_seqs4,chunked prefill2048,prefix caching OFF,async scheduling OFF and BF16 weights. Both CUDA-graph support gates passed; actual FULL_AND_PIECEWISE compilation is common. Both B16 and F4 use XQA decode; F4 prefill uses NVFP4 FA2. XQA receives packed NVFP4 data and block scales. Neither`nvfp4_fa2=True`nor`impl.use_xqa=None`implies XQA decode is unused.'))
        bodies.append(txt('정확히8192/16384개의 입력 token IDs를 Qwen template 전체(roles·assistant prefix 포함)로 동결해 completions endpoint에 전달했습니다. 합성 filler는 사전 생성에서만 조정했고 질문·사실은 자르지 않았습니다. 각 길이의 같은8 prompt를 C1/2/4에서 세 번 사용합니다. 순서는 B16→F4 / F4→B16 / B16→F4입니다. 출력은 ignore_eos=True,128토큰이며 자연 종료 sanity와 구분합니다. 각 요청 timeout180초에는 client slot 대기도 포함됩니다.', 'Exactly8192/16384 input IDs include the full Qwen template, roles and assistant prefix, sent to the completions endpoint. Only synthetic filler was adjusted before registration; facts/questions were never truncated. The same8 prompts/length are used at C1/2/4 for three rounds. KV order is B16→F4 / F4→B16 / B16→F4. Throughput uses ignore_eos=True and128 output tokens, separate from natural-end sanity. The180-second request timeout includes client-slot waiting.'))
        bodies[-1] += '\n\n' + txt('Makespan은 닫힌8요청 집합의 launch→마지막 client 응답 종료입니다. 실제 timestamp는 HTTP 수신 후 raw SSE 파싱까지 포함하며 HTTPclose만의 별도 시각은 기록하지 않았습니다. req/s=성공 요청/makespan, output token/s=관측 output tokens/makespan. Client TTFT는 전송→첫 nonempty token-ID event, decode 평균은 마지막−첫 token-bearing event를 n−1로 나눈 값입니다. SSE chunk 간격을 token ITL로 쓰지 않았습니다. 엔진 queue/decode는 전용 서버 histogram sum/count의 block 구간 차이입니다. 메모리는 배경 점유를 포함하는 device 표본과 Torch allocated/reserved를 분리했습니다.', 'Makespan is launch→last client-response terminal for the closed8-request set. The timestamp includes raw SSE parsing after HTTP receipt; exact HTTPclose is not separately timestamped. req/s=successful requests/makespan; output tokens/s=observed output tokens/makespan. Client TTFT is dispatch→first nonempty token-ID event. Mean client decode is(last−first token-bearing event)/(n−1). SSE chunk gaps are not individual-token ITL. Engine queue/decode comes from dedicated-server histogram sum/count interval differences. Device memory includes background use and is separate from Torch allocated/reserved.')
        bodies.append(cap + '\n' + perf + '\n' + resources + '\n' + sanity + '\n' + costs + '\n' + startups)
        bodies[-1] += '\n\n' + txt('작은 NHD/HND 검사에서 같은 압축 cache의 두 dequant 방식 최대차이는0이었습니다. BF16 원본 대비 상대 norm 오차는 각각 ', 'The small NHD/HND checks found zero maximum difference between two dequant interpretations of the same compressed cache. Relative norm errors versus original BF16 were ') + ', '.join(f(r['bf16_original_vs_quantized_relative_norm_error'], 6) for r in data['numeric_scope']['same_compressed_dequant']) + '. ' + txt('이 값은 양자화 오차이며 decoder 간 불일치가 아닙니다. 짧은512-token P0 eager 입력과32-token 생성에서 실제 attention36층은 두 조건 모두 유한했습니다. 전체 모델 logits의 독립 유한성·전체 KL/PPL은 미측정입니다.', 'These are quantization errors, not decoder disagreements. Actual attention outputs were finite across36 layers for both conditions in the short512-token P0 eager probe with32 generated tokens. Independent full-model-logit finiteness and full KL/PPL were not measured.')
        bodies.append(txt('같은 pool에서 F4의 여유 슬롯과 정상 attention kernel 선택이 queue·선점·시간과 함께 달라집니다. 전체 구성의 관측 차이이며 양자화 산술만의 원인으로 분리하지 않습니다. 세 round 비율과 범위를 모두 보여주고 요청 latency 재표집으로 makespan의 좁은 CI를 만들지 않았습니다. 동일8 prompt의 반복을24개 독립 과제로 세지 않습니다.', 'F4 changes free slot capacity, normal attention-kernel selection, queueing and time within the same pool. These are observed configuration differences, not an isolated arithmetic cause. All three round ratios/ranges are shown; no request-latency bootstrap fabricates a narrow makespan interval. Repeated8 prompts are not24 independent tasks.'))
        bodies[-1] += '\n\n' + txt('계측 주석: 재사용 CacheInspector의 `cudagraph_policy`는 과거 eager 설명 상수였습니다. raw 필드는 보존하고 실제 `compilation_mode`, startup capture 로그와 동결 launch 설정으로 graph를 판정했습니다. 모델 파라미터 비교는 모든 named parameter의 앞뒤8개 값에 대한 signature이며 전체 GPU weight hash가 아닙니다. 파일 단위 모델 shard hash는 원 snapshot과 다시 일치했습니다.', 'Instrumentation note: the reused CacheInspector`cudagraph_policy` is an old constant eager-description string. Raw fields remain unchanged; graph status uses actual`compilation_mode`, startup capture logs and frozen launch settings. Parameter signatures sample the first/last8 values of each named parameter, not full GPU tensors. File-level model-shard hashes were rechecked against the original snapshot.')
        bodies.append((conclusion_ko if ko else conclusion_en) + '\n\n' + txt('이전 agent 연구는 B16 0/48·F4 6/48, 같은12개 DEV 과제의 메뉴/cap 반복입니다. 기준선 gate NOT_MET·원 실패·amendment01~08·소스 hash와 CPU 감사 원점수 변경0을 보존했습니다. F4의 세 task 성공을 일반 업무 우위로 확대하지 않습니다.', 'The original agent study retains B16 0/48,F4 6/48 across the same12 DEV tasks repeated by menu/cap. NOT_MET baseline gate, failures,amendments01–08,source hashes and zero CPU-audit score changes are preserved. Three successful F4 tasks do not establish general workflow superiority.') + '\n\n' + table(['Scope', 'Status'], [['Native NVFP4 KV storage/read ·36 layers', 'VERIFIED'], ['Fixed4GiB capacity ·36 timed blocks/288requests', 'MEASURED'], ['Copy canary/open-text sanity', 'LIMITED ·16 paired prompts'], ['Full KL/PPL · agent-quality improvement ·100K context', 'NOT_EVALUATED'], ['Agent P2/P3 · weight W4 · training · prefix reuse', 'NOT_RUN'], ['GitHub Pages', 'BUILDER_READY · MANUAL_DEPLOY_NOT_RUN']]))
        bodies.append('[CPU / GPU commands](REPRODUCE' + suffix + ') · [Stage map](STAGE_MAP.md) · [Raw rows](' + tech + '/results/) · [Protocol](' + tech + '/specs/protocol.json) · [Execution source freeze](' + tech + '/provenance/execution_freeze.json)\n\n' + txt('실행 source SHA256: ', 'Execution source SHA256: ') + '`' + data['execution_source_sha256'] + '`\n\n' + txt('Git base·실행 소스 hash·모델 revision·page build revision은 다른 identity입니다. 원 연구449개 파일 중447개를 손실 없는 gzip 또는 동일 바이트로 공개 보존했습니다. 개인 scratch 경로를 담은 패키징 helper2개는 원본 hash만 기록하고 공개에서 제외했습니다. 원 사용자 worktree의 기존 파일은 변경하지 않았습니다.', 'Git base,execution source hash,model revision and page-build revision identify different objects. Of449 original files,447 are publicly retained byte-identically or as lossless gzip. Two packaging helpers with personal scratch paths are omitted, retaining original hashes. Existing files in the user’s original worktree are unchanged.') + '\n\n' + '[vLLM v0.32.0](https://github.com/vllm-project/vllm/releases/tag/v0.32.0) · [Pinned FlashInfer backend](https://github.com/vllm-project/vllm/blob/v0.32.0/vllm/v1/attention/backends/flashinfer.py) · [Completion protocol](https://github.com/vllm-project/vllm/blob/v0.32.0/vllm/entrypoints/openai/completion/protocol.py) · [NOTICE](NOTICE.md)\n\n' + txt('NVFP4 커널은 upstream vLLM/FlashInfer 제공입니다. 직접 기여는 통합·실제 경로/용량 검사·고정 workload 계측·CPU 감사·문서입니다. Codex가 구현과 별도 계산 검토를 보조했으며 사람의 독립 심사나 외부 GPU 재현으로 표시하지 않습니다.', 'Upstream vLLM/FlashInfer provide the NVFP4 kernels. Contributions are integration,path/capacity inspection,fixed-workload measurement,CPU auditing and documentation. Codex assisted implementation and separate calculation review; this is not human peer review or external GPU reproduction.'))
        for i, (h, anchor, body) in enumerate(zip(headings, anchors, bodies)):
            report += '\n<a id="' + anchor + '"></a>\n\n## ' + str(i + 1) + '. ' + h + '\n\n' + body + '\n'
        worker = data['worker']
        report += '\n' + txt('이번 누적 GPU worker wall: ', 'Cumulative GPU-worker wall: ') + f(worker['wall_seconds'], 3) + 's /7200s. ' + txt('모델 load·작은 검사·graph gate·warmup·sanity·metric·I/O를 포함하며 GPU busy나 serving 가속률이 아닙니다. 설치·모델 다운로드·새 weight artifact 생성은0회입니다.', 'Includes load,small checks,graph gates,warmup,sanity,metrics and I/O; it is not GPU-busy time or serving speedup. No installs,model downloads or weight-artifact builds were performed.') + '\n'
        (case / ('REPORT' + suffix)).write_text(report)
        reproduce = '# ' + txt('Case016 재현: 모델 없는 검산과 별도 GPU 실측', 'Case016 reproduction: model-free checks and separate GPU measurement') + '\n\n' + txt('저장소 root에서 실행합니다. CPU 경로는 Python3 표준 라이브러리만 필요하며 Torch/Transformers/vLLM을 import하거나 서버에 접속하지 않습니다. 출력은 새 외부 디렉터리여야 합니다.', 'Run from the repository root. The CPU route needs only Python3 standard library, without Torch/Transformers/vLLM imports or server requests. Choose a new external output directory.') + '\n\n```bash\npython3 -B cases/016-kv-agent-bench/publication/run_checks.py --output /tmp/case016-check-new --tests\n```\n\n' + txt('이 명령은 공개 manifest→원형447개 복원→11개 과거 source view260개 hash 검사→기존96 episode/478 SSE 재생→새 기술 raw SSE 재조립·용량/처리량 재계산→표시 JSON 일치 순서입니다. 과거33+3개 검사와 감사15개를 회귀 재실행하며 EVAL 생성 검사1개는 제외합니다. 신규 기술 검사16개와 과거 검사 수를 분리합니다. CPU replay는 GPU inference 재현이 아닙니다.', 'The route verifies the public manifest,restores447 originals,checks260 hashes in11 historical source views,replays96 episodes/478 SSE records,reassembles new technical SSE and recomputes capacity/throughput,then matches display JSON. It reruns33+3 historical tests and15 audit tests; one EVAL-generating test is excluded. The16 new technical tests are counted separately. CPU replay does not reproduce GPU inference.')
        reproduce += '\n\n```bash\nTECH=cases/016-kv-agent-bench/followups/nvfp4-technical-r1\nPYTHONDONTWRITEBYTECODE=1 PYTHONPATH="$TECH/src" python3 -B -m nvfp4_technical.audit --root "$TECH" --output /tmp/case016-raw-new\nPYTHONDONTWRITEBYTECODE=1 PYTHONPATH="$TECH/src" python3 -B -m nvfp4_technical.plots --analysis /tmp/case016-raw-new --output /tmp/case016-figures-new\n```\n\n' + txt('CSV와8개 SVG는 위 명령으로 재생성합니다. 기존 analysis/figure는 덮어쓰지 않습니다.', 'These commands regenerate CSVs and8 SVGs into new directories; retained analysis/figures are not overwritten.')
        reproduce += '\n\n```bash\npython3 -B cases/016-kv-agent-bench/publication/prepare_gpu_copy.py --output /tmp/case016-gpu-input-new\n```\n\n' + txt('위 CPU 명령은 모델을 실행하지 않고 재현용 source/input 사본만 만듭니다.', 'This CPU command prepares only a source/input copy, without running a model.')
        reproduce += '\n\n## ' + txt('별도 GPU 재현 조건', 'Separate GPU conditions') + '\n\n' + txt('원 model/환경/payload는 포함하지 않습니다. Python3.12.14,vLLM0.32.0,FlashInfer0.7.0.post1,Torch2.13.0/CUDA13.0,driver610.88을 사용한 기존 격리 환경과 고정 revision의 로컬 Qwen snapshot이 필요합니다. source build나 driver 변경은 수행하지 않았습니다. 원 환경 lock·wheel SHA는 [기록](provenance/environment.json)에 있습니다.', 'Model/environment/payloads are not included. Reproduction requires the pinned local Qwen snapshot and isolated runtime used here:Python3.12.14,vLLM0.32.0,FlashInfer0.7.0.post1,Torch2.13.0/CUDA13.0,driver610.88. No source build or driver change was performed. The [environment record](provenance/environment.json) retains the lock and wheel SHA.')
        reproduce += '\n\n' + txt('완료된 run root를 다시 실행하면 overwrite를 거절합니다. 새 scratch case 사본에 준비된 protocol/data와 읽기 전용 원 src를 두고, private runtime JSON에 다음 필드를 지정합니다. 경로는 사용자 장비의 실제 위치입니다.', 'The runner refuses to overwrite a completed run. Use a new scratch case copy containing the frozen protocol/data and read-only original src. Supply these fields in a private runtime JSON,using actual local paths:') + '\n\n```json\n{"python":"<EXISTING_GPU_PYTHON>","snapshot":"<PINNED_LOCAL_SNAPSHOT>","private_root":"<NEW_OWNED_SCRATCH>","original_case":"<SCRATCH_CASE>","technical_root":"<SCRATCH_CASE>/followups/nvfp4-technical-r1","port":8152}\n```\n\n```bash\nPYTHONDONTWRITEBYTECODE=1 PYTHONPATH="$TECH/src" "$CASE016_GPU_PYTHON" -B -m nvfp4_technical.runner --runtime "$CASE016_PRIVATE_RUNTIME"\n```\n\n' + txt('위 GPU 명령은 실행 가능한 별도 경로이며 CPU 확인에서 호출하지 않습니다. server command는 runner/server.py에 고정되어 있습니다. 새 GPU 재현에는 기존 results/와 execution_freeze를 원형에서 분리한 빈 출력 사본이 필요하며 새 결과는 새 freeze를 가집니다. 원 run과 같은 결과라고 자동 간주하지 않습니다. 원 snapshot·다른 서비스·기존 환경은 변경하지 않고 소유한 loopback 서버만 관리합니다.', 'The GPU command is a separate executable path,never called by CPU verification. server.py pins the launch command. A new GPU rerun needs a scratch input/source copy with an empty results directory and a separately retained historical execution freeze; its new freeze is a new run identity. It is not automatically equivalent to this run. Keep the snapshot,other services and existing environment unchanged; manage only the owned loopback server.')
        (case / ('REPRODUCE' + suffix)).write_text(reproduce + '\n')
    (case / 'STAGE_MAP.md').write_text('# Case016 stage map\n\n| Stage | Evidence / result | Reproduction boundary |\n|---|---|---|\n| Original agent P0/P1 | B16 0/48,F4 6/48; baseline NOT_MET | Original source,amendments01–08 and96 records retained losslessly |\n| Baseline CPU audit | 96 episodes,478 requests; score changes0 | Closed unchanged1.95MB audit bundle; CPU fixture replay |\n| Native KV technical P1-T | Same4GiB pool,36 blocks,288 timed requests | New native vLLM/FlashInfer GPU requests; independent SSE/scalar audit |\n| Agent P2/P3 | NOT_RUN | No new agent study |\n| Pages | Builder/CI prepared | Manual publish=true was not dispatched |\n\n[Original byte mapping](publication/provenance/original_mapping.json) · [Original P1 source freeze](results/p1_r1/code_freeze.json) · [Historical root report](publication/originals/agent-study/REPORT.ko.md) · [Technical protocol](followups/nvfp4-technical-r1/specs/protocol.json)\n\nHistorical root documents retain their exact bytes. Their original relative links work in the restored `agent-original` view created by the CPU wrapper. Large repeated JSON/HTML is stored as gzip; the wrapper checks decompressed original SHA256 before execution. Two private-path packaging helpers are not experiment sources and are omitted from public files. No original scientific file is replaced by the new report.\n')


